L7_1 = " \227\130\183\227\131\171\227\131\147\227\130\162\227\129\149\227\130\147\227\129\174\232\168\128\227\129\134\227\130\136\227\129\134\227\129\171\227\128\129\228\187\138\227\129\175\227\129\147\227\129\174\231\138\182\230\179\129\227\130\146\230\137\147\233\150\139\227\129\167\227\129\141\227\129\170\227\129\145\227\130\140\227\129\176\227\128\129\231\167\129\227\129\159\227\129\161\227\129\171\227\129\175\229\190\140\227\129\140\227\129\130\227\130\138\227\129\190\227\129\155\227\130\147\227\128\130"
L6_1.m_Talk_JPN = L7_1
