L6_1.m_Talk_VTN = L7_1
L7_1 = "\228\189\134\229\176\177\229\131\143\229\184\140\229\176\148\232\150\135\229\168\133\232\175\180\231\154\132\233\130\163\230\160\183\239\188\140\229\166\130\230\158\156\228\184\141\232\174\190\230\179\149\230\137\173\232\189\172\231\156\188\228\184\139\231\154\132\229\177\128\233\157\162\239\188\140\230\136\145\228\187\172\229\176\177\228\187\128\228\185\136\233\131\189\230\178\161\230\156\137\228\186\134\227\128\130"
